  /** Whether the Network can automatically scale its subnet size based on the number of active DHCP leases. */
  autoScaleEnabled: boolean;
  /** IPv4 DHCP configuration for this network. If this field is omitted or null, DHCP is not working and hosts must get an address statically or from another server in this broadcast domain. */
  dhcpConfiguration?: GatewayManagedIPv4DHCPConfiguration;
  hostIpAddress: string;
  /** List of NAT Outbound Configurations defining which IP addresses are used for NAT translation. This array must contain all WAN interfaces with `static` or `PPPoE` IPv4 connection configuration. */
  natOutboundIpAddressConfiguration?: Array<WANNATOutboundConfiguration>;
