/** Authorizes network access to a guest client. Client must be a guest. This action cancels existing active authorization (if exists), creates a new one with new limits and resets guest traffic counters. */
export interface GuestAccessAuthorizationRequest {
  /** Always AUTHORIZE_GUEST_ACCESS here: it names this variant. */
  action: "AUTHORIZE_GUEST_ACCESS";
  /** (Optional) data usage limit in megabytes */
  dataUsageLimitMBytes?: number;
  /** (Optional) download rate limit in kilobits per second */
  rxRateLimitKbps?: number;
  /** (Optional) how long (in minutes) the guest will be authorized to access the network. If not specified, the default limit is used from the site settings */
  timeLimitMinutes?: number;
  /** (Optional) upload rate limit in kilobits per second */
  txRateLimitKbps?: number;
}

/** The "Guest access authorization response" schema of the UniFi Network API. */
export interface GuestAccessAuthorizationResponse {
  /** Always AUTHORIZE_GUEST_ACCESS here: it names this variant. */
  action: "AUTHORIZE_GUEST_ACCESS";
  /** Granted guest authorization */
  grantedAuthorization: GuestAuthorizationDetails;
  /** (Optional) Revoked authorization in case the guest was already authorized at the time of this request */
  revokedAuthorization?: GuestAuthorizationDetails;
}

/** The "Guest access details" schema of the UniFi Network API. */
export interface GuestAccessDetails {
  /** Always GUEST here: it names this variant. */
  type: "GUEST";
  authorization?: GuestAuthorizationDetails;
  authorized: boolean;
}

/** The "Guest access overview" schema of the UniFi Network API. */
export interface GuestAccessOverview {
  /** Always GUEST here: it names this variant. */
  type: "GUEST";
  authorized: boolean;
}

/** Unauthorizes network access and disconnects a guest client. */
export interface GuestAccessUnauthorizationRequest {
  /** Always UNAUTHORIZE_GUEST_ACCESS here: it names this variant. */
  action: "UNAUTHORIZE_GUEST_ACCESS";
}

/** The "Guest access unauthorization response" schema of the UniFi Network API. */
export interface GuestAccessUnauthorizationResponse {
  /** Always UNAUTHORIZE_GUEST_ACCESS here: it names this variant. */
  action: "UNAUTHORIZE_GUEST_ACCESS";
  /** Revoked guest authorization */
  revokedAuthorization: GuestAuthorizationDetails;
}

/** The "Guest authorization details" schema of the UniFi Network API. */
export interface GuestAuthorizationDetails {
  /** Guest authorization method (API, Voucher etc) */
  authorizationMethod: "VOUCHER" | "API" | "OTHER";
  /** Timestamp when the guest has been authorized */
  authorizedAt: string;
  /** (Optional) data usage limit in megabytes */
  dataUsageLimitMBytes?: number;
  /** Timestamp when the guest will get automatically unauthorized */
  expiresAt: string;
  /** (Optional) download rate limit in kilobits per second */
  rxRateLimitKbps?: number;
  /** (Optional) upload rate limit in kilobits per second */
  txRateLimitKbps?: number;
  usage?: GuestAuthorizationUsageDetails;
}

/** The "Guest authorization usage details" schema of the UniFi Network API. */
export interface GuestAuthorizationUsageDetails {
  bytes: number;
  durationSec: number;
  rxBytes: number;
  txBytes: number;
}

/** The "Hotspot voucher creation request" schema of the UniFi Network API. */
export interface HotspotVoucherCreationRequest {
  /** (Optional) limit for how many different guests can use the same voucher to authorize network access */
  authorizedGuestLimit?: number;
  /** Number of vouchers to generate */
  count?: number;
  /** (Optional) data usage limit in megabytes */
  dataUsageLimitMBytes?: number;
  /** Voucher note, duplicated across all generated vouchers */
  name: string;
  /** (Optional) download rate limit in kilobits per second */
  rxRateLimitKbps?: number;
  /** How long (in minutes) the voucher will provide access to the network since authorization of the first guest. Subsequently connected guests, if allowed, will share the same expiration time. */
  timeLimitMinutes: number;
  /** (Optional) upload rate limit in kilobits per second */
  txRateLimitKbps?: number;
}

/** The "Hotspot voucher detail page" schema of the UniFi Network API. */
export interface HotspotVoucherDetailPage {
  count: number;
  data: Array<HotspotVoucherDetails>;
  limit: number;
  offset: number;
  totalCount: number;
}

/** The "Hotspot voucher details" schema of the UniFi Network API. */
export interface HotspotVoucherDetails {
  /** (Optional) timestamp when the voucher has been activated (authorization time of the first guest) */
  activatedAt?: string;
  /** For how many guests the voucher has been used to authorize network access */
  authorizedGuestCount: number;
  /** (Optional) limit for how many different guests can use the same voucher to authorize network access */
  authorizedGuestLimit?: number;
  /** Secret code to active the voucher using the Hotspot portal */
  code: string;
  createdAt: string;
  /** (Optional) data usage limit in megabytes */
  dataUsageLimitMBytes?: number;
  /** Whether the voucher has been expired and can no longer be used to authorize network access */
  expired: boolean;
  /** (Optional) timestamp when the voucher will become expired. All guests using the voucher will be unauthorized from network access */
  expiresAt?: string;
  id: string;
  /** Voucher note, may contain duplicate values across multiple vouchers */
  name: string;
  /** (Optional) download rate limit in kilobits per second */
  rxRateLimitKbps?: number;
  /** How long (in minutes) the voucher will provide access to the network since authorization of the first guest. Subsequently connected guests, if allowed, will share the same expiration time. */
  timeLimitMinutes: number;
  /** (Optional) upload rate limit in kilobits per second */
  txRateLimitKbps?: number;
}

